import { z } from "zod";

// Non-secret configuration that statically prerendered pages need at build time:
// canonical URLs and the public image host. Kept apart from lib/env/server.ts so a build
// never requires runtime secrets (production images are built without them).

const httpUrl = z.url({ protocol: /^https?$/ });

const publicConfigSchema = z.object({
  APP_URL: httpUrl,
  /** Base URL of the public product-image bucket or CDN (never the private files). */
  S3_PUBLIC_BASE_URL: httpUrl.optional(),
});

export type PublicConfig = z.infer<typeof publicConfigSchema>;

let cached: PublicConfig | undefined;

export function publicConfig(): PublicConfig {
  cached ??= publicConfigSchema.parse({
    APP_URL: process.env.APP_URL,
    S3_PUBLIC_BASE_URL: process.env.S3_PUBLIC_BASE_URL || undefined,
  });
  return cached;
}

/** Absolute URL of the store for metadata, sitemaps and structured data. */
export function appUrl(): URL {
  return new URL(publicConfig().APP_URL);
}

/**
 * Public URL of a product image. Keys are generated by the server (Phase 5), so each
 * path segment only needs encoding, never validation against traversal.
 */
export function publicImageUrl(storageKey: string): string | null {
  const base = publicConfig().S3_PUBLIC_BASE_URL;
  if (!base) return null;
  const path = storageKey.split("/").map(encodeURIComponent).join("/");
  return `${base.replace(/\/+$/, "")}/${path}`;
}
